/** Picker categories in display order (KB84 tabs). */
export const CODE_CATEGORIES: readonly { id: CodeCategory; zh: string; en: string }[] = [
  { id: 'key', zh: '按键', en: 'Keys' },
  { id: 'media', zh: '多媒体键', en: 'Media' },
  { id: 'mouse', zh: '鼠标键', en: 'Mouse' },
  { id: 'function', zh: '操控键', en: 'Function' },
  { id: 'power', zh: '电源键', en: 'Power' },
  { id: 'special', zh: '设备功能', en: 'Device functions' },
]

function freezeAll(items: CodeInfo[]): readonly CodeInfo[] {
  for (const item of items) Object.freeze(Object.freeze(item).wire)
  return Object.freeze(items)
}

const byValue = new Map(CODES.map((c) => [c.value, c]))
const byId = new Map(CODES.map((c) => [c.id, c]))
const byIdLower = new Map(CODES.map((c) => [c.id.toLowerCase(), c]))

/** Older / alternative KeyboardEvent.code spellings. */
const EVENT_CODE_ALIASES: Record<string, string> = {
  OSLeft: 'MetaLeft',
  OSRight: 'MetaRight',
  VolumeUp: 'AudioVolumeUp',
  VolumeDown: 'AudioVolumeDown',
  VolumeMute: 'AudioVolumeMute',
}

export function codeByValue(value: number): CodeInfo | undefined {
  return byValue.get(value)
}

/** Exact id match first, then a case-insensitive one ("keya" → KeyA). */
export function codeById(id: string): CodeInfo | undefined {
  return byId.get(id) ?? byIdLower.get(id.toLowerCase())
}

export interface ResolvedCode {
  value: number
  /** Bytes for a single-code action; a fresh array the caller may keep. */
  wire: number[]
  info?: CodeInfo
}

/** Resolves a profile CodeRef: a code id, or a raw number 1..255 (unknown numbers have no info and wire [value]). */
export function resolveCodeRef(ref: string | number): ResolvedCode | null {
  if (typeof ref === 'number') {
    if (!Number.isInteger(ref) || ref < 1 || ref > 255) return null
    const info = byValue.get(ref)
    return info ? { value: ref, wire: [...info.wire], info } : { value: ref, wire: [ref] }
  }
  const info = codeById(ref)
  return info ? { value: info.value, wire: [...info.wire], info } : null
}

/** Maps a KeyboardEvent.code to the device code (undefined for keys the device has no code for, e.g. IntlBackslash). */
export function codeForKeyboardEventCode(code: string): CodeInfo | undefined {
  const info = byId.get(EVENT_CODE_ALIASES[code] ?? code)
  return info && (info.category === 'key' || info.category === 'media' || info.category === 'power') ? info : undefined
}

const hex = (v: number) => `0x${v.toString(16).toUpperCase().padStart(2, '0')}`

/** Human name of a CodeRef; unknown numbers become "Device function 0xNN". */
export function codeLabel(ref: string | number, lang: 'zh' | 'en'): string {
  const r = resolveCodeRef(ref)
  if (!r) return String(ref)
  if (r.info) return r.info[lang]
  return lang === 'zh' ? `设备功能 ${hex(r.value)}` : `Device function ${hex(r.value)}`
}

/** Key-cap text of a CodeRef (≤ 6 characters for known codes). */
export function codeShort(ref: string | number): string {
  const r = resolveCodeRef(ref)
  if (!r) return String(ref)
  return r.info?.short ?? hex(r.value)
}
